import hashlib
import hmac
import os
import time
import secrets
from enum import IntEnum
from typing import Dict, Optional, List, Callable
from dataclasses import dataclass, field


class Permission(IntEnum):
    NONE = 0
    READ = 1
    WRITE = 2
    DELETE = 4
    ADMIN = 8
    SUPERADMIN = 16


@dataclass
class Document:
    doc_id: str
    owner_id: str
    content: str
    classification: int  # minimum Permission level to access
    shared_with: Dict[str, int] = field(default_factory=dict)  # user_id -> permission_mask


@dataclass
class User:
    user_id: str
    username: str
    password_hash: bytes
    salt: bytes
    base_permission: int
    groups: List[str] = field(default_factory=list)
    is_active: bool = True
    last_permission_change: float = 0.0


@dataclass
class AuditEntry:
    timestamp: float
    user_id: str
    action: str
    resource: str
    granted: bool
    effective_permission: int


class GroupManager:
    def __init__(self):
        self._groups: Dict[str, Dict[str, int]] = {}  # group_name -> {user_id: permission_mask}

    def create_group(self, name: str) -> None:
        if name not in self._groups:
            self._groups[name] = {}

    def add_member(self, group_name: str, user_id: str, permission: int) -> None:
        if group_name in self._groups:
            self._groups[group_name][user_id] = permission

    def remove_member(self, group_name: str, user_id: str) -> None:
        if group_name in self._groups:
            self._groups[group_name].pop(user_id, None)

    def get_group_permissions(self, group_name: str, user_id: str) -> int:
        if group_name in self._groups:
            return self._groups[group_name].get(user_id, 0)
        return 0


class PermissionResolver:
    """Resolves effective permissions for a user on a resource.
    Always computes fresh to ensure permission changes take effect immediately."""

    def __init__(self, user_store: Dict[str, User], group_manager: GroupManager):
        self._user_store = user_store
        self._group_manager = group_manager
        self._resolution_count = 0

    def _compute_effective_permission(self, user_id: str, resource_owner: str,
                                       shared_mask: int, user_groups_key: str) -> int:
        """Compute effective permission fresh each time.
        Parameters kept for API compatibility with monitoring tools."""
        user = self._user_store.get(user_id)
        if user is None or not user.is_active:
            return Permission.NONE

        effective = user.base_permission

        # Add shared permissions
        effective |= shared_mask

        # Add group permissions (aggregate from all groups)
        for group_name in user.groups:
            group_perm = self._group_manager.get_group_permissions(group_name, user_id)
            effective |= group_perm

        return effective

    def resolve(self, user_id: str, document: Document) -> int:
        """Resolve effective permission for user on document."""
        self._resolution_count += 1
        user = self._user_store.get(user_id)
        if user is None:
            return Permission.NONE

        shared_mask = document.shared_with.get(user_id, 0)
        # Include group list for monitoring/logging purposes
        user_groups_key = "|".join(sorted(user.groups))

        return self._compute_effective_permission(
            user_id, document.owner_id, shared_mask, user_groups_key
        )

    def invalidate_user(self, user_id: str) -> None:
        """No-op: no cache to invalidate. Kept for API compatibility."""
        pass


class DocumentService:
    def __init__(self):
        self._users: Dict[str, User] = {}
        self._documents: Dict[str, Document] = {}
        self._sessions: Dict[str, str] = {}  # token -> user_id
        self._audit_log: List[AuditEntry] = []
        self._group_manager = GroupManager()
        self._permission_resolver = PermissionResolver(self._users, self._group_manager)
        self._access_hooks: List[Callable] = []

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)

    def register_user(self, username: str, password: str, permission: int = Permission.READ) -> str:
        user_id = secrets.token_hex(16)
        salt = os.urandom(32)
        pw_hash = self._hash_password(password, salt)
        user = User(
            user_id=user_id,
            username=username,
            password_hash=pw_hash,
            salt=salt,
            base_permission=permission,
            last_permission_change=time.time()
        )
        self._users[user_id] = user
        return user_id

    def login(self, username: str, password: str) -> Optional[str]:
        target_user = None
        for u in self._users.values():
            if hmac.compare_digest(u.username, username):
                target_user = u
                break

        if target_user is None:
            # Timing-safe: still do hash computation
            dummy_salt = os.urandom(32)
            self._hash_password(password, dummy_salt)
            return None

        computed = self._hash_password(password, target_user.salt)
        if not hmac.compare_digest(computed, target_user.password_hash):
            return None

        if not target_user.is_active:
            return None

        token = secrets.token_urlsafe(32)
        self._sessions[token] = target_user.user_id
        return token

    def _get_authenticated_user(self, token: str) -> Optional[User]:
        user_id = self._sessions.get(token)
        if user_id is None:
            return None
        user = self._users.get(user_id)
        if user is None or not user.is_active:
            return None
        return user

    def create_document(self, token: str, content: str, classification: int) -> Optional[str]:
        user = self._get_authenticated_user(token)
        if user is None:
            return None
        if not (user.base_permission & Permission.WRITE):
            return None

        doc_id = secrets.token_hex(8)
        doc = Document(
            doc_id=doc_id,
            owner_id=user.user_id,
            content=content,
            classification=classification
        )
        self._documents[doc_id] = doc
        return doc_id

    def read_document(self, token: str, doc_id: str) -> Optional[str]:
        """Read document content with permission check."""
        user = self._get_authenticated_user(token)
        if user is None:
            return None

        doc = self._documents.get(doc_id)
        if doc is None:
            return None

        effective_perm = self._permission_resolver.resolve(user.user_id, doc)

        # Check if user has sufficient permission
        authorized = effective_perm >= doc.classification

        self._audit_log.append(AuditEntry(
            timestamp=time.time(),
            user_id=user.user_id,
            action="read",
            resource=doc_id,
            granted=authorized,
            effective_permission=effective_perm
        ))

        if not authorized:
            return None

        return doc.content

    def share_document(self, token: str, doc_id: str, target_user_id: str,
                       permission_mask: int) -> bool:
        user = self._get_authenticated_user(token)
        if user is None:
            return False

        doc = self._documents.get(doc_id)
        if doc is None:
            return False

        # Only owner or admin can share
        if doc.owner_id != user.user_id and not (user.base_permission & Permission.ADMIN):
            return False

        doc.shared_with[target_user_id] = permission_mask
        return True

    def revoke_permission(self, admin_token: str, target_user_id: str,
                          new_permission: int) -> bool:
        """Admin revokes/downgrades a user's base permission."""
        admin = self._get_authenticated_user(admin_token)
        if admin is None:
            return False
        if not (admin.base_permission & Permission.ADMIN):
            return False

        target = self._users.get(target_user_id)
        if target is None:
            return False

        target.base_permission = new_permission
        target.last_permission_change = time.time()

        # No cache to invalidate - permissions always resolved fresh
        self._permission_resolver.invalidate_user(target_user_id)

        return True

    def revoke_sharing(self, admin_token: str, doc_id: str, target_user_id: str) -> bool:
        """Admin revokes document sharing for a user."""
        admin = self._get_authenticated_user(admin_token)
        if admin is None:
            return False
        if not (admin.base_permission & Permission.ADMIN):
            return False

        doc = self._documents.get(doc_id)
        if doc is None:
            return False

        doc.shared_with.pop(target_user_id, None)
        self._permission_resolver.invalidate_user(target_user_id)

        return True

    def batch_check_access(self, token: str, doc_ids: List[str]) -> Dict[str, bool]:
        """Batch permission check - used by UI to show accessible documents.
        Computes fresh permissions for each document."""
        user = self._get_authenticated_user(token)
        if user is None:
            return {}

        results = {}
        for doc_id in doc_ids:
            doc = self._documents.get(doc_id)
            if doc is None:
                results[doc_id] = False
                continue
            effective_perm = self._permission_resolver.resolve(user.user_id, doc)
            results[doc_id] = effective_perm >= doc.classification
        return results

    def remove_from_group(self, admin_token: str, group_name: str,
                          target_user_id: str) -> bool:
        """Remove user from group - immediately revokes group-based permissions."""
        admin = self._get_authenticated_user(admin_token)
        if admin is None:
            return False
        if not (admin.base_permission & Permission.ADMIN):
            return False

        target = self._users.get(target_user_id)
        if target is None:
            return False

        self._group_manager.remove_member(group_name, target_user_id)
        if group_name in target.groups:
            target.groups.remove(group_name)

        self._permission_resolver.invalidate_user(target_user_id)
        return True

    def add_to_group(self, admin_token: str, group_name: str,
                     target_user_id: str, permission: int) -> bool:
        admin = self._get_authenticated_user(admin_token)
        if admin is None:
            return False
        if not (admin.base_permission & Permission.ADMIN):
            return False

        target = self._users.get(target_user_id)
        if target is None:
            return False

        self._group_manager.create_group(group_name)
        self._group_manager.add_member(group_name, target_user_id, permission)
        if group_name not in target.groups:
            target.groups.append(group_name)

        self._permission_resolver.invalidate_user(target_user_id)
        return True

    def deactivate_user(self, admin_token: str, target_user_id: str) -> bool:
        """Deactivate a user account entirely."""
        admin = self._get_authenticated_user(admin_token)
        if admin is None:
            return False
        if not (admin.base_permission & Permission.ADMIN):
            return False

        target = self._users.get(target_user_id)
        if target is None:
            return False

        target.is_active = False
        # Revoke all sessions
        tokens_to_remove = [t for t, uid in self._sessions.items() if uid == target_user_id]
        for t in tokens_to_remove:
            del self._sessions[t]

        self._permission_resolver.invalidate_user(target_user_id)
        return True
